package ru.neverland.townycompanies;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
import static ru.neverland.townycompanies.ContractAccounting.*;

/** Explicit estimates and receipt-backed allocations, isolated from the existing bank ledger. */
public final class CompanyProfit {
    private final JavaPlugin plugin;private final CompanyService service;private final ContractAccountsStore store;private final boolean enabled;
    private record Cache(State costs,CompanyLedger.State bank,Map<UUID,Summary> summaries){}
    private Cache cache;
    private String unavailable="";
    public CompanyProfit(JavaPlugin plugin,CompanyService service){this.plugin=plugin;this.service=service;store=new ContractAccountsStore(plugin.getDataFolder().toPath().resolve("contract-accounts.yml"));enabled=plugin.getConfig().getBoolean("accounting.enabled",true);if(enabled)try{store.load();}catch(Exception error){unavailable="Учёт затрат требует проверки администрацией";plugin.getLogger().warning(unavailable+": "+error.getMessage());}}
    public boolean available(){return enabled&&unavailable.isEmpty();}public boolean saving(){return store.busy();}public boolean writable(){return available()&&store.writable();}
    public String reason(){return !enabled?"Учёт затрат отключён администрацией":unavailable;}
    public State state(){return store.state();}
    private void read(){if(!available())throw new IllegalStateException(reason());}
    private CompanyData.Company manager(Player p){read();if(!SuiteState.held())throw new IllegalStateException("Нужна согласованная операция учёта");if(SuiteState.frozen(plugin.getName())||!plugin.isEnabled()||!writable())throw new IllegalStateException("Запись затрат сейчас недоступна");return service.manage(p,false,true);}
    public List<Report> reports(Player p){read();var company=service.own(p);return state().reports().values().stream().filter(r->r.company().equals(company.id())).sorted(Comparator.comparingLong(Report::updated).reversed()).toList();}
    public Report report(Player p,UUID contract){read();var c=service.own(p);var r=state().reports().get(reportId(c.id(),contract));if(r==null)throw new IllegalArgumentException("Сначала создайте смету этого договора");return r;}
    public Report proposal(Player p,UUID contract){var c=manager(p);if(state().reports().containsKey(reportId(c.id(),contract)))throw new IllegalArgumentException("Смета этого договора уже есть в разделе затрат");var offer=service.contracts.offers(c.town()).stream().filter(o->contract.toString().equals(o.get("id"))).findFirst().orElseThrow(()->new IllegalArgumentException("Договор больше не доступен"));String assigned=(String)offer.get("company");if(!assigned.isEmpty()&&!assigned.equals(c.id().toString()))throw new IllegalArgumentException("Этот договор выполняет другая компания");if(!Boolean.TRUE.equals(offer.get("funded"))||!(offer.get("rewardCents") instanceof Long reward))throw new IllegalArgumentException("Для подтверждённой сметы нужен обновлённый и доступный раздел городских контрактов");return new Report(reportId(c.id(),contract),c.id(),c.town(),contract,(String)offer.get("name"),(String)offer.get("target"),((Number)offer.get("goal")).intValue(),reward,Budget.unknown(),null,"",p.getUniqueId(),System.currentTimeMillis(),1);}
    public CompletionStage<State> create(Player p,Report quoted){var fresh=proposal(p,quoted.contract());if(!fresh.id().equals(quoted.id())||!fresh.title().equals(quoted.title())||!fresh.target().equals(quoted.target())||fresh.goal()!=quoted.goal()||fresh.reward()!=quoted.reward())throw new IllegalArgumentException("Условия договора изменились. Проверьте смету заново");var before=state();return commit(p,before,ContractAccounting.put(before,quoted,0),quoted,"CREATE","Создана смета без расходования средств");}
    private Report managed(Player p,UUID contract,long revision){var company=manager(p);var r=report(p,contract);if(!company.id().equals(r.company())||r.revision()!=revision)throw new IllegalArgumentException("Смета или компания изменились. Повторите выбор");return r;}
    public CompletionStage<State> budget(Player p,UUID contract,long revision,Budget budget){var r=managed(p,contract,revision);var before=state();var next=r.edit(budget,r.declaredMaterials(),r.materialNote(),p.getUniqueId(),System.currentTimeMillis());return commit(p,before,ContractAccounting.put(before,next,revision),next,"BUDGET","Плановые материалы/зарплаты/налоги: "+budget);}
    public CompletionStage<State> materials(Player p,UUID contract,long revision,Long cents,String note){var r=managed(p,contract,revision);var before=state();var next=r.edit(r.budget(),cents,note,p.getUniqueId(),System.currentTimeMillis());return commit(p,before,ContractAccounting.put(before,next,revision),next,"MATERIALS","Заявленная стоимость материалов: "+cents+" коп.; "+note);}
    private void assigned(Report r){var receipt=service.ledger.state().receipts().get(r.contract());if(receipt!=null&&receipt.company().equals(r.company())&&receipt.town().equals(r.town()))return;boolean mine=service.contracts.offers(r.town()).stream().anyMatch(o->r.contract().toString().equals(o.get("id"))&&r.company().toString().equals(o.get("company")));if(!mine)throw new IllegalArgumentException("Привязывать платежи можно к своему принятому или завершённому договору");}
    public CompletionStage<State> allocate(Player p,UUID contract,long revision,UUID paymentId,long cents,UUID allocationId,long created){var r=managed(p,contract,revision);assigned(r);var payment=service.ledger.state().payments().get(paymentId);if(payment==null)throw new IllegalArgumentException("Платёж не найден в подтверждённом журнале компании");var before=state();var next=ContractAccounting.allocate(before,r.id(),revision,payment,allocationId,cents,p.getUniqueId(),created);return commit(p,before,next,r,"ALLOCATE","Распределено "+cents+" коп. платежа "+paymentId+"; ID "+allocationId);}
    public CompletionStage<State> reverse(Player p,UUID contract,long revision,UUID allocation){var r=managed(p,contract,revision);var before=state();var a=before.allocations().get(allocation);if(a==null||!a.report().equals(r.id()))throw new IllegalArgumentException("Эта затрата относится к другой смете");var next=ContractAccounting.reverse(before,allocation,revision,p.getUniqueId(),System.currentTimeMillis());return commit(p,before,next,r,"REVERSE","Снято распределение "+allocation+"; банковский платёж не отменяется");}
    private CompletionStage<State> commit(Player p,State before,State next,Report report,String action,String detail){var actor=AuditTrail.player(p.getUniqueId());var company=service.ledger.company(report.company());var party=new AuditRecord.Party("COMPANY",company.id().toString(),company.name(),company.town().toString());return store.commit(before,next).thenApply(image->{if(image!=before&&!AuditTrail.record(plugin,"accounting",report.id()+":"+image.revision(),"COMPANY_CONTRACT_COST","COMPLETED",actor,party,party,"",0,"",action+"; договор "+report.contract()+"; "+detail))plugin.getLogger().warning("Смета сохранена; журнал затрат требует проверки");return image;}).whenComplete((image,error)->{if(error!=null&&!store.writable())plugin.getLogger().log(java.util.logging.Level.WARNING,"Изменение учёта договоров не подтверждено; прежний отчёт сохранён. Проверьте хранилище перед повторным запуском раздела",error);});}
    public Summary summary(Report report){read();var costs=state();var bank=service.ledger.state();if(cache==null||cache.costs()!=costs||cache.bank()!=bank)cache=new Cache(costs,bank,ContractAccounting.summaries(costs,bank));var result=cache.summaries().get(report.id());if(result==null)throw new IllegalArgumentException("Смета больше не доступна");return result;}
    public Map<String,Object> snapshot(UUID companyId,UUID contract){try(var guard=SuiteState.guard()){if(!available())return Map.of("available",false,"reason",reason());var r=state().reports().get(reportId(companyId,contract));if(r==null)return Map.of("available",false,"reason","Смета ещё не создана");var s=summary(r);var map=new LinkedHashMap<String,Object>();map.put("available",true);map.put("company",r.company().toString());map.put("contract",r.contract().toString());map.put("revision",r.revision());map.put("quotedRewardCents",r.reward());map.put("receivedKnown",s.received()!=null);if(s.received()!=null)map.put("receivedCents",s.received());map.put("refundCents",s.refund());map.put("plannedMarginKnown",s.plannedMargin()!=null);if(s.plannedMargin()!=null)map.put("plannedMarginCents",s.plannedMargin());map.put("paidWagesCents",s.paidWages());map.put("paidTaxesCents",s.paidTaxes());map.put("declaredMaterialsKnown",s.declaredMaterials()!=null);if(s.declaredMaterials()!=null)map.put("declaredMaterialsCents",s.declaredMaterials());map.put("accountedMarginKnown",s.accountedMargin()!=null);if(s.accountedMargin()!=null)map.put("accountedMarginCents",s.accountedMargin());map.put("unverifiedAllocations",s.unverified());map.put("unallocatedCompanyWagesCents",s.unallocatedWages());map.put("unallocatedCompanyTaxesCents",s.unallocatedTaxes());map.put("materialNote",r.materialNote());return Map.copyOf(map);}}
    public CompletionStage<Void> prepareClose(){return store.prepareClose();}public void awaitClosed(){store.awaitClosed();}
}
